"use client"

import {
  useEffect,
  useState,
  type CSSProperties,
  type ComponentProps,
  type ReactNode,
} from "react"
import { motion, useReducedMotion } from "motion/react"
import { cva } from "class-variance-authority"
import { MessageSquare } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Sheet, SheetContent, SheetTitle } from "@/components/ui/sheet"
import { cn } from "@/lib/utils"
import {
  AgentChatProvider,
  useAgentChat,
  useAgentContext,
} from "./agent-chat-context"
import { AgentChatBody } from "./agent-chat-body"
import { useAgentChatPosition } from "./use-agent-chat-position"
import type { AgentChatMode } from "./types"
import type { AgentChatLabels } from "./config"

const agentChatTriggerVariants = cva("", {
  variants: {
    variant: {
      fab: "fixed right-4 bottom-4 z-40 size-12 rounded-full shadow-lg",
      button: "",
    },
  },
})

function AgentChatTrigger({
  className,
  variant = "fab",
  ...props
}: Omit<ComponentProps<typeof Button>, "variant"> & {
  variant?: "fab" | "button"
}) {
  const { open, setOpen, mode, labels } = useAgentContext()
  if (variant === "fab" && (mode !== "floating" || open)) return null
  return (
    <Button
      data-slot="agent-chat-trigger"
      data-state={open ? "open" : "closed"}
      data-mode={mode}
      className={cn(agentChatTriggerVariants({ variant }), className)}
      variant={variant === "fab" ? "default" : "outline"}
      size={variant === "fab" ? "icon" : "sm"}
      aria-label={open ? labels.closeTrigger : labels.openTrigger}
      aria-expanded={open}
      {...props}
      onClick={(event) => {
        props.onClick?.(event)
        if (!event.defaultPrevented) setOpen(!open)
      }}
    >
      <MessageSquare />
      {variant === "button" ? labels.title : null}
    </Button>
  )
}

/** 从工作区发起一个上下文问题，仍使用 Provider 中的同一段会话。 */
function AgentChatSuggestion({
  question,
  children,
  className,
  ...props
}: ComponentProps<typeof Button> & { question: string; children?: ReactNode }) {
  const { chat, setOpen, updateScroll } = useAgentContext()
  const busy = chat.status === "streaming" || chat.status === "submitted"
  return (
    <Button
      data-slot="agent-chat-suggestion"
      variant="link"
      className={className}
      {...props}
      disabled={busy || props.disabled}
      onClick={(event) => {
        props.onClick?.(event)
        if (event.defaultPrevented) return
        setOpen(true)
        updateScroll({ follow: true })
        void chat.sendMessage({ text: question })
      }}
    >
      {children ?? question}
    </Button>
  )
}

function AgentChatPanel({
  className,
  id,
  draggable = true,
}: Pick<ComponentProps<"aside">, "className" | "id"> & {
  draggable?: boolean
}) {
  const { mode, open, setOpen, title, labels } = useAgentContext()
  const [mobile, setMobile] = useState(false)
  const [width, setWidth] = useState(400)
  const reduced = useReducedMotion()
  const movable = mode === "floating" && !mobile && draggable
  const { panelRef, position, headerProps, onMoveKeyDown, reset } =
    useAgentChatPosition({
      enabled: movable && open,
      active: mode === "floating" && !mobile && open,
    })
  useEffect(() => {
    const query = window.matchMedia("(max-width: 767px)")
    const update = () => setMobile(query.matches)
    update()
    query.addEventListener("change", update)
    return () => query.removeEventListener("change", update)
  }, [])
  if (!open) return null
  if (mobile)
    return (
      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent
          id={id}
          data-slot="agent-chat-panel"
          data-mode={mode}
          data-state="open"
          side="bottom"
          showCloseButton={false}
          className={cn(
            "h-[92dvh]! max-h-[92dvh] gap-0 rounded-t-2xl motion-reduce:transition-none",
            className,
          )}
        >
          <SheetTitle className="sr-only">{title}</SheetTitle>
          <AgentChatBody />
        </SheetContent>
      </Sheet>
    )
  return (
    <motion.aside
      ref={panelRef}
      data-draggable={movable || undefined}
      id={id}
      data-slot="agent-chat-panel"
      data-state="open"
      aria-label={title}
      onKeyDown={(event) => {
        if (event.key === "Escape") {
          event.preventDefault()
          setOpen(false)
        }
      }}
      data-mode={mode}
      initial={reduced ? false : { opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: reduced ? 0 : 0.2 }}
      style={
        {
          "--agent-width": `${width}px`,
          ...(mode === "floating" && position
            ? {
                left: position.x,
                top: position.y,
                right: "auto",
                bottom: "auto",
              }
            : {}),
        } as CSSProperties
      }
      className={cn(
        "flex min-h-0 flex-col bg-background text-foreground data-[dragging]:cursor-grabbing data-[dragging]:select-none",
        mode === "embedded"
          ? "relative h-full w-(--agent-width) shrink-0 border-l border-edge"
          : "fixed right-4 bottom-4 z-40 h-[min(600px,calc(100dvh-2rem))] w-[400px] max-w-[calc(100vw-2rem)] overflow-hidden rounded-2xl border border-edge shadow-xl",
        className,
      )}
    >
      {mode === "embedded" ? (
        <div
          data-slot="agent-chat-resize-handle"
          role="separator"
          aria-label={labels.resize}
          aria-orientation="vertical"
          aria-valuemin={320}
          aria-valuemax={640}
          aria-valuenow={width}
          tabIndex={0}
          className="absolute inset-y-0 -left-1 w-2 cursor-col-resize touch-none rounded select-none focus-visible:bg-primary/20 focus-visible:outline-none"
          onKeyDown={(event) => {
            if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
              event.preventDefault()
              setWidth((value) =>
                Math.max(
                  320,
                  Math.min(640, value + (event.key === "ArrowLeft" ? 16 : -16)),
                ),
              )
            }
          }}
          onPointerDown={(event) => {
            event.currentTarget.setPointerCapture(event.pointerId)
            event.preventDefault()
          }}
          onPointerMove={(event) => {
            if (event.currentTarget.hasPointerCapture(event.pointerId))
              setWidth(
                Math.max(
                  320,
                  Math.min(
                    640,
                    event.currentTarget.parentElement!.getBoundingClientRect()
                      .right - event.clientX,
                  ),
                ),
              )
          }}
          onPointerUp={(event) => {
            event.currentTarget.releasePointerCapture(event.pointerId)
          }}
        />
      ) : null}
      <AgentChatBody
        draggable={movable}
        headerProps={headerProps}
        onMoveKeyDown={onMoveKeyDown}
        onResetPosition={reset}
      />
    </motion.aside>
  )
}

export {
  AgentChatProvider,
  AgentChatPanel,
  AgentChatTrigger,
  AgentChatSuggestion,
  useAgentChat,
  agentChatTriggerVariants,
}
export type { AgentChatMode, AgentChatLabels }

"use client"

import { useLayoutEffect, useRef, useState, type ComponentProps } from "react"
import {
  ArrowDown,
  ArrowUp,
  Bot,
  GripHorizontal,
  PanelRight,
  Plus,
  Square,
  X,
} from "lucide-react"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"
import { AgentChatMessage } from "./chat-message"
import { useAgentContext } from "./agent-chat-context"

function AgentChatBody({
  draggable = false,
  headerProps,
  onMoveKeyDown,
  onResetPosition,
}: {
  draggable?: boolean
  headerProps?: ComponentProps<"header">
  onMoveKeyDown?: ComponentProps<"button">["onKeyDown"]
  onResetPosition?: () => void
}) {
  const {
    labels,
    chat,
    title,
    mode,
    toggleMode,
    setOpen,
    draft,
    setDraft,
    suggestions,
    scroll,
    updateScroll,
  } = useAgentContext()
  const viewport = useRef<HTMLDivElement>(null)
  const input = useRef<HTMLTextAreaElement>(null)
  const [following, setFollowing] = useState(scroll.current.follow)
  const busy = chat.status === "streaming" || chat.status === "submitted"
  // 切换外壳或关闭再打开时恢复滚动；流式更新仅在用户位于底部时跟随。
  useLayoutEffect(() => {
    const node = viewport.current
    if (node)
      node.scrollTop = scroll.current.follow
        ? node.scrollHeight
        : scroll.current.top
  }, [mode, scroll])
  useLayoutEffect(() => {
    const node = viewport.current
    if (node && scroll.current.follow) node.scrollTop = node.scrollHeight
  }, [chat.messages, scroll])
  useLayoutEffect(() => {
    if (!input.current) return
    input.current.style.height = "auto"
    input.current.style.height = `${Math.min(input.current.scrollHeight, 160)}px`
  }, [draft])
  const send = (text: string) => {
    if (!text.trim() || busy) return
    updateScroll({ follow: true })
    setFollowing(true)
    setDraft("")
    void chat.sendMessage({ text: text.trim() })
  }
  return (
    <div
      data-slot="agent-chat-body"
      data-state={busy ? "streaming" : "idle"}
      className="contents"
    >
      <header
        data-slot="agent-chat-header"
        {...headerProps}
        className={cn(
          "flex shrink-0 items-center gap-2 border-b border-edge px-3 py-3",
          draggable &&
            "cursor-grab touch-none select-none data-[dragging]:cursor-grabbing",
        )}
      >
        {draggable ? (
          <Button
            data-slot="agent-chat-move-handle"
            variant="ghost"
            size="icon-sm"
            aria-label={labels.moveWindow}
            className="cursor-grab in-data-[dragging]:cursor-grabbing"
            onKeyDown={onMoveKeyDown}
            onClick={(event) => {
              if (event.detail === 0) onResetPosition?.()
            }}
          >
            <GripHorizontal aria-hidden="true" />
          </Button>
        ) : null}
        <Avatar className="size-8">
          <AvatarFallback>
            <Bot className="size-4" />
          </AvatarFallback>
        </Avatar>
        <div className="min-w-0 flex-1">
          <h2 className="truncate text-sm font-medium">{title}</h2>
          <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
            <span
              className={cn(
                "size-1.5 rounded-full",
                busy
                  ? "bg-primary motion-safe:animate-pulse"
                  : "bg-muted-foreground",
              )}
            />
            {busy ? labels.thinking : labels.idle}
          </p>
        </div>
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label={labels.newChat}
          disabled={busy}
          onClick={() => {
            chat.setMessages([])
            chat.clearError()
            setDraft("")
            updateScroll({ top: 0, follow: true })
          }}
        >
          <Plus />
        </Button>
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label={mode === "embedded" ? labels.floatMode : labels.embedMode}
          aria-pressed={mode === "embedded"}
          onClick={toggleMode}
        >
          <PanelRight />
        </Button>
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label={labels.closePanel}
          onClick={() => setOpen(false)}
        >
          <X />
        </Button>
      </header>
      <div
        ref={viewport}
        role="log"
        aria-label={labels.history}
        aria-live="polite"
        aria-relevant="additions"
        className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-4 py-5"
        onScroll={(event) => {
          const node = event.currentTarget
          const follow =
            node.scrollHeight - node.scrollTop - node.clientHeight < 48
          updateScroll({ top: node.scrollTop, follow })
          setFollowing(follow)
        }}
      >
        {chat.messages.length ? (
          <div className="flex flex-col gap-7">
            {chat.messages.map((message, index) => (
              <AgentChatMessage
                key={message.id}
                message={message}
                live={busy && index === chat.messages.length - 1}
                busy={busy}
                regenerate={() => {
                  updateScroll({ follow: true })
                  void chat.regenerate({ messageId: message.id })
                }}
              />
            ))}
          </div>
        ) : (
          <div className="flex h-full flex-col justify-center gap-5 py-6">
            <Bot className="size-8 text-primary" />
            <div>
              <p className="text-lg font-medium tracking-tight">
                {labels.welcome}
              </p>
              <p className="mt-2 text-sm leading-7 text-muted-foreground">
                {labels.welcomeDescription}
              </p>
            </div>
            <div className="flex flex-col gap-2">
              {suggestions.map((question) => (
                <Button
                  key={question}
                  variant="outline"
                  className="h-auto justify-start py-3 text-left whitespace-normal"
                  onClick={() => send(question)}
                >
                  {question}
                  <ArrowUp
                    data-icon="inline-end"
                    className="ml-auto shrink-0"
                  />
                </Button>
              ))}
            </div>
          </div>
        )}
      </div>
      {!following && chat.messages.length > 0 ? (
        <Button
          variant="secondary"
          size="sm"
          className="mx-auto mb-2"
          onClick={() => {
            updateScroll({ follow: true })
            setFollowing(true)
            if (viewport.current)
              viewport.current.scrollTop = viewport.current.scrollHeight
          }}
        >
          <ArrowDown />
          {labels.latest}
        </Button>
      ) : null}
      {chat.error ? (
        <div role="alert" className="px-4 pb-2 text-sm text-destructive">
          {labels.error}
          <Button
            variant="ghost"
            size="sm"
            disabled={busy}
            onClick={() => {
              void chat.regenerate()
            }}
          >
            {labels.retry}
          </Button>
        </div>
      ) : null}
      <p className="sr-only" role="status" aria-live="polite">
        {busy
          ? labels.generating
          : chat.messages.length
            ? labels.updated
            : labels.ready}
      </p>
      <form
        className="flex shrink-0 flex-col gap-2 border-t border-edge p-3 pb-[max(0.75rem,env(safe-area-inset-bottom))]"
        onSubmit={(event) => {
          event.preventDefault()
          send(draft)
        }}
      >
        <Textarea
          name="message"
          autoComplete="off"
          ref={input}
          aria-label={labels.input}
          placeholder={labels.placeholder}
          value={draft}
          maxLength={4000}
          className="max-h-40 min-h-16 resize-none"
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={(event) => {
            if (
              event.key === "Enter" &&
              !event.shiftKey &&
              !event.nativeEvent.isComposing
            ) {
              event.preventDefault()
              send(draft)
            }
          }}
        />
        <div className="flex items-center justify-between gap-2">
          <p className="text-xs text-muted-foreground">{labels.newline}</p>
          {busy ? (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => {
                void chat.stop()
              }}
            >
              <Square />
              {labels.stop}
            </Button>
          ) : (
            <Button
              type="submit"
              size="icon-sm"
              aria-label={labels.send}
              disabled={!draft.trim()}
            >
              <ArrowUp />
            </Button>
          )}
        </div>
      </form>
    </div>
  )
}

export { AgentChatBody }

"use client"

import { useLayoutEffect, useRef, useState, type ComponentProps } from "react"

type Position = { x: number; y: number }
const STORAGE_KEY = "travinsy:agent-chat:position"
const INTERACTIVE =
  "button:not([data-slot='agent-chat-move-handle']), a, input, textarea, select, [role='button']"

function constrain(position: Position, panel: HTMLElement): Position {
  return {
    x: Math.max(0, Math.min(window.innerWidth - panel.offsetWidth, position.x)),
    // 高度不足时仍保留整个标题栏，桌面常规尺寸下将整个窗口收回视口。
    y: Math.max(
      0,
      Math.min(
        window.innerHeight - Math.min(panel.offsetHeight, window.innerHeight),
        position.y,
      ),
    ),
  }
}

function defaultPosition(panel: HTMLElement): Position {
  return constrain(
    {
      x: window.innerWidth - panel.offsetWidth - 16,
      y: window.innerHeight - panel.offsetHeight - 16,
    },
    panel,
  )
}

function writePosition(panel: HTMLElement, position: Position) {
  panel.style.left = `${position.x}px`
  panel.style.top = `${position.y}px`
  panel.style.right = "auto"
  panel.style.bottom = "auto"
}

function storePosition(position: Position | null) {
  try {
    if (position) localStorage.setItem(STORAGE_KEY, JSON.stringify(position))
    else localStorage.removeItem(STORAGE_KEY)
  } catch {
    // 浏览器禁止存储时，窗口在当前会话中仍可正常移动。
  }
}

function useAgentChatPosition({
  enabled,
  active,
}: {
  enabled: boolean
  active: boolean
}) {
  const panelRef = useRef<HTMLElement>(null)
  const current = useRef<Position | null>(null)
  const restored = useRef(false)
  const [position, setPosition] = useState<Position | null>(null)
  const drag = useRef<{
    pointerId: number
    handle: HTMLElement
    start: Position
    origin: Position
  } | null>(null)

  function commit(next: Position | null) {
    current.current = next
    setPosition(next)
    storePosition(next)
  }

  function finish() {
    const session = drag.current
    if (!session) return
    drag.current = null
    panelRef.current?.removeAttribute("data-dragging")
    session.handle.removeAttribute("data-dragging")
    if (session.handle.hasPointerCapture(session.pointerId))
      session.handle.releasePointerCapture(session.pointerId)
    commit(current.current)
  }

  useLayoutEffect(() => {
    if (!active) return
    const panel = panelRef.current
    if (!panel) return
    if (!restored.current) {
      restored.current = true
      try {
        const saved: unknown = JSON.parse(
          localStorage.getItem(STORAGE_KEY) ?? "null",
        )
        if (
          saved &&
          typeof saved === "object" &&
          "x" in saved &&
          "y" in saved &&
          typeof saved.x === "number" &&
          Number.isFinite(saved.x) &&
          typeof saved.y === "number" &&
          Number.isFinite(saved.y)
        )
          current.current = { x: saved.x, y: saved.y }
      } catch {
        // 损坏或不可读的缓存回退到默认右下角。
      }
    }
    const update = () => {
      const next = current.current ? constrain(current.current, panel) : null
      writePosition(panel, next ?? defaultPosition(panel))
      if (next) {
        current.current = next
        setPosition(next)
        storePosition(next)
      }
    }
    update()
    window.addEventListener("resize", update)
    const observer = new ResizeObserver(update)
    observer.observe(panel)
    return () => {
      window.removeEventListener("resize", update)
      observer.disconnect()
      for (const property of ["left", "top", "right", "bottom"])
        panel.style.removeProperty(property)
    }
  }, [active])

  useLayoutEffect(() => {
    if (!enabled) finish()
    return () => finish()
    // finish 只读取 ref；流式消息更新不能解除正在进行的指针捕获。
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled])

  function reset() {
    const panel = panelRef.current
    if (!enabled || !panel) return
    finish()
    // 复位直接定位，无动画，同样适用于 prefers-reduced-motion。
    writePosition(panel, defaultPosition(panel))
    commit(null)
  }

  const headerProps: ComponentProps<"header"> = enabled
    ? {
        onPointerDown(event) {
          if (
            !event.isPrimary ||
            event.button !== 0 ||
            drag.current ||
            (event.target as Element).closest(INTERACTIVE)
          )
            return
          const panel = panelRef.current
          if (!panel) return
          event.preventDefault()
          if (
            (event.target as Element).closest(
              "[data-slot='agent-chat-move-handle']",
            )
          )
            (event.target as Element).closest<HTMLElement>("button")?.focus()
          const origin = current.current ?? defaultPosition(panel)
          drag.current = {
            pointerId: event.pointerId,
            handle: event.currentTarget,
            start: { x: event.clientX, y: event.clientY },
            origin,
          }
          current.current = origin
          event.currentTarget.setPointerCapture(event.pointerId)
          event.currentTarget.setAttribute("data-dragging", "true")
          panel.setAttribute("data-dragging", "true")
        },
        onPointerMove(event) {
          const session = drag.current
          const panel = panelRef.current
          if (!session || !panel || session.pointerId !== event.pointerId)
            return
          const next = constrain(
            {
              x: session.origin.x + event.clientX - session.start.x,
              y: session.origin.y + event.clientY - session.start.y,
            },
            panel,
          )
          current.current = next
          // 不提交 React state，避免每帧重渲染消息和输入框。
          writePosition(panel, next)
        },
        onPointerUp(event) {
          if (drag.current?.pointerId === event.pointerId) finish()
        },
        onPointerCancel(event) {
          if (drag.current?.pointerId === event.pointerId) finish()
        },
        onLostPointerCapture(event) {
          if (drag.current?.pointerId === event.pointerId) finish()
        },
        onDoubleClick(event) {
          if (!(event.target as Element).closest(INTERACTIVE)) reset()
        },
      }
    : {}

  function onMoveKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    if (!enabled || event.altKey || event.ctrlKey || event.metaKey) return
    if (event.key === "Home") {
      event.preventDefault()
      reset()
      return
    }
    const direction = {
      ArrowLeft: [-1, 0],
      ArrowRight: [1, 0],
      ArrowUp: [0, -1],
      ArrowDown: [0, 1],
    }[event.key]
    const panel = panelRef.current
    if (!direction || !panel) return
    event.preventDefault()
    finish()
    const start = current.current ?? defaultPosition(panel)
    const step = event.shiftKey ? 64 : 16
    const next = constrain(
      { x: start.x + direction[0] * step, y: start.y + direction[1] * step },
      panel,
    )
    writePosition(panel, next)
    commit(next)
  }

  return { panelRef, position, headerProps, onMoveKeyDown, reset }
}

export { useAgentChatPosition }

"use client"

import {
  createContext,
  useContext,
  useRef,
  useState,
  type ReactNode,
} from "react"
import { useChat } from "@ai-sdk/react"
import type { ChatTransport, UIMessage } from "ai"
import { useControllableState } from "@/registry/hooks/use-controllable-state"
import {
  DEFAULT_LABELS,
  agentSuggestions,
  type AgentChatLabels,
} from "./config"
import type { AgentChatMode } from "./types"
import { createMockTransport } from "./mock-transport"

type ChatState = ReturnType<typeof useChat<UIMessage>>
type AgentContextValue = {
  mode: AgentChatMode
  setMode: (mode: AgentChatMode) => void
  toggleMode: () => void
  open: boolean
  setOpen: (open: boolean) => void
  chat: ChatState
  title: string
  labels: AgentChatLabels
  suggestions: string[]
  draft: string
  setDraft: (draft: string) => void
  scroll: { current: { top: number; follow: boolean } }
  updateScroll: (value: Partial<{ top: number; follow: boolean }>) => void
}
const AgentContext = createContext<AgentContextValue | null>(null)
function useAgentContext() {
  const context = useContext(AgentContext)
  if (!context) throw new Error("请在 AgentChatProvider 内使用助手组件")
  return context
}
function useAgentChat() {
